// Purpose: Validate Sweep or Commit. Keep this deterministic and fail closed.
const r = $json, operation = String(r.operation || 'ENUMERATE');
if (!['ENUMERATE', 'COMMIT'].includes(operation))
    throw new Error('INVALID_SWEEP_OPERATION');
for (const k of ['run_id', 'source_code'])
    if (!r[k])
        throw new Error(`Missing ${k}`);
if (operation === 'COMMIT') {
    for (const k of ['run_upper_bound', 'downstream_receipt_sha256', 'expected_cursor_version'])
        if (r[k] === undefined || r[k] === null || r[k] === '')
            throw new Error(`Missing ${k}`);
    if (!/^[a-f0-9]{64}$/.test(String(r.downstream_receipt_sha256)))
        throw new Error('DOWNSTREAM_RECEIPT_HASH_INVALID');
}
return [{ json: { ...r, operation } }];

// Purpose: Freeze Trusted Cursor Window. Keep this deterministic and fail closed.
const request = $json;
for (const field of ['folder_id', 'senders', 'subjects', 'window_start']) {
    if (request[field] === undefined || request[field] === null || request[field] === '') {
        throw new Error(`Missing ${field}`);
    }
}
if (!Array.isArray(request.senders) || !request.senders.length) {
    throw new Error('Trusted sender allowlist is required');
}
if (!Array.isArray(request.subjects) || !request.subjects.length) {
    throw new Error('Trusted subject-fragment allowlist is required');
}
const start = new Date(request.window_start);
const upper = request.run_upper_bound ? new Date(request.run_upper_bound) : new Date();
if (!Number.isFinite(start.valueOf()) || !Number.isFinite(upper.valueOf()) || !(start < upper) || upper > new Date()) {
    throw new Error('Invalid frozen cursor window');
}
const senders = request.senders.map(value => String(value).trim().toLowerCase());
const subjects = request.subjects.map(value => String(value).trim()).filter(Boolean);
const maxMessages = Number(request.max_messages ?? 500);
if (!Number.isInteger(maxMessages) || maxMessages < 1 || maxMessages > 5000) {
    throw new Error('max_messages must be an integer from 1 through 5000');
}
const quoteOData = value => `'${String(value).replaceAll("'", "''")}'`;
const senderFilter = senders.map(value => `from/emailAddress/address eq ${quoteOData(value)}`).join(' or ');
const subjectFilter = subjects.map(value => `contains(subject,${quoteOData(value)})`).join(' or ');
return [{
        json: {
            ...request,
            senders,
            subjects,
            max_messages: maxMessages,
            run_upper_bound: upper.toISOString(),
            server_filter: `(${senderFilter}) and (${subjectFilter})`,
        },
    }];

// Purpose: Gate Outlook Circuit. Keep this deterministic and fail closed.
const now = new Date(), row = $json?.provider_code ? $json : { state: 'CLOSED', transient_failure_count: 0 }, retry = row.retry_after ? new Date(row.retry_after) : null;
if (row.state === 'OPEN' && retry && retry > now)
    throw new Error('PROVIDER_CIRCUIT_OPEN:MICROSOFT_GRAPH');
return [{ json: { provider_code: 'MICROSOFT_GRAPH', state: row.state === 'OPEN' ? 'HALF_OPEN' : 'CLOSED', transient_failure_count: Number(row.transient_failure_count || 0), last_error_class: row.last_error_class || '', opened_at: row.opened_at || null, retry_after: row.retry_after || null, readback_verified: false, updated_at: now.toISOString() } }];

// Purpose: Aggregate Exact Window Heartbeat. Keep this deterministic and fail closed.
const contract = $('Freeze Trusted Cursor Window').first().json, start = new Date(contract.window_start), upper = new Date(contract.run_upper_bound);
const scanned = $input.all().map(item => item.json).filter(message => message?.id);
if (scanned.length > contract.max_messages) throw new Error('SOURCE_RESULT_LIMIT_EXCEEDED:' + scanned.length);
const messages = scanned.filter(message => {
    const sender = String(message.from?.emailAddress?.address || message.sender?.emailAddress?.address || '').toLowerCase(), subject = String(message.subject || '').toLowerCase(), received = new Date(message.receivedDateTime);
    return contract.senders.includes(sender) && contract.subjects.some(fragment => subject.includes(fragment.toLowerCase())) && received >= start && received < upper;
}).sort((left, right) => String(left.receivedDateTime).localeCompare(String(right.receivedDateTime)) || String(left.id).localeCompare(String(right.id)));
return [{ json: { run_id: contract.run_id, source_code: contract.source_code, folder_id: contract.folder_id, senders: contract.senders, subjects: contract.subjects, onedrive_parent_id: contract.onedrive_parent_id, window_start: contract.window_start, run_upper_bound: contract.run_upper_bound, pagination_exhausted: true, pages_fetched: null, scanned_count: scanned.length, matched_count: messages.length, heartbeat: messages.length === 0, messages } }];

// Purpose: Verify Receipt and Return Sweep. Keep this deterministic and fail closed.
const e = $('Aggregate Exact Window Heartbeat').first().json, o = $json;
for (const k of ['run_id','source_code','window_start','run_upper_bound','scanned_count','matched_count','heartbeat'])
    if (String(o[k]) !== String(e[k])) throw new Error('ACQUISITION_RECEIPT_MISMATCH:' + k);
if (o.pagination_exhausted !== true || o.cursor_commit_eligible !== false) throw new Error('ACQUISITION_RECEIPT_STATE_MISMATCH');
return [{ json: { ...e, folder_id: e.folder_id, senders: e.senders, subjects: e.subjects, onedrive_parent_id: e.onedrive_parent_id, receipt_readback_verified: true, cursor_commit_eligible: false } }];

// Purpose: Verify Downstream Persistence Proof. Keep this deterministic and fail closed.
const r = $('Validate Sweep or Commit').first().json, o = $json;
if (o.run_upper_bound !== r.run_upper_bound || o.pagination_exhausted !== true || o.cursor_commit_eligible !== false) throw new Error('ACQUISITION_NOT_COMMIT_ELIGIBLE');
if (o.attachment_verification_barrier !== 'VERIFIED' || o.email_evidence_receipt_barrier !== 'VERIFIED' || Number(o.email_evidence_receipts_verified) !== Number(o.matched_count)) throw new Error('DOWNSTREAM_ARCHIVE_AND_EMAIL_BARRIER_MISSING');
return [{ json: { ...r, folder_id: r.folder_id, senders: r.senders, subjects: r.subjects, onedrive_parent_id: r.onedrive_parent_id, window_start: o.window_start, scanned_count: Number(o.scanned_count), matched_count: Number(o.matched_count), heartbeat: Boolean(o.heartbeat), attachment_identity_keys: o.attachment_identity_keys || [], email_evidence_receipts_verified: Number(o.email_evidence_receipts_verified), email_evidence_receipt_barrier: o.email_evidence_receipt_barrier } }];

// Purpose: Build Cursor CAS Update. Keep this deterministic and fail closed.
const r = $('Verify Downstream Persistence Proof').first().json, o = $json, expected = Number(r.expected_cursor_version);
if (o.source_code !== r.source_code || !Number.isInteger(expected) || expected < 0 || Number(o.cursor_version) !== expected) throw new Error('SOURCE_CURSOR_VERSION_CONFLICT');
const next = new Date(r.run_upper_bound), prior = new Date(o.cursor_value);
if (!Number.isFinite(next.valueOf()) || !Number.isFinite(prior.valueOf()) || next <= prior) throw new Error('SOURCE_CURSOR_NON_MONOTONIC');
if (o.committed_run_id === r.run_id && o.cursor_value === r.run_upper_bound) throw new Error('SOURCE_CURSOR_ALREADY_COMMITTED');
return [{ json: { ...r, prior_cursor_version: expected, next_cursor_version: expected + 1 } }];

// Purpose: Compare CAS Cursor Readback. Keep this deterministic and fail closed.
const e = $('Build Cursor CAS Update').first().json, o = $json;
if (o.cursor_value !== e.run_upper_bound || Number(o.cursor_version) !== e.next_cursor_version || o.committed_run_id !== e.run_id)
    throw new Error('SOURCE_CURSOR_CAS_READBACK_MISMATCH');
return [{ json: e }];

// Purpose: Return Verified Cursor Commit. Keep this deterministic and fail closed.
const e = $('Build Cursor CAS Update').first().json, o = $json;
if (o.downstream_receipt_sha256 !== e.downstream_receipt_sha256 || o.cursor_commit_eligible !== true)
    throw new Error('ACQUISITION_TERMINAL_READBACK_MISMATCH');
return [{ json: { status: 'CURSOR_COMMITTED', run_id: e.run_id, source_code: e.source_code, cursor: e.run_upper_bound, cursor_version: e.next_cursor_version, downstream_receipt_sha256: e.downstream_receipt_sha256 } }];

// Purpose: Shape Immutable Message Inventory. Keep this deterministic and fail closed.
const sweep = $('Verify Receipt and Return Sweep').first().json;
if (sweep.immutable_inventory === false) throw new Error('IMMUTABLE_ENUMERATION_REQUIRED');
const rows = Array.isArray(sweep.messages) ? sweep.messages : [], seen = new Set();
if (!rows.length) return [{ json: { ...sweep, messages: [], empty_inventory: true, immutable_inventory: true } }];
return rows.map(row => {
    const message = row?.message && typeof row.message === 'object' ? row.message : row, messageId = String(row?.message_id || message?.id || '').trim();
    if (!messageId || seen.has(messageId)) throw new Error('IMMUTABLE_MESSAGE_ID_MISSING_OR_DUPLICATE');
    seen.add(messageId);
    return { json: { ...message, id: messageId, message_id: messageId, source_code: sweep.source_code, folder_id: sweep.folder_id, senders: sweep.senders, subjects: sweep.subjects, window_start: sweep.window_start, window_end: sweep.run_upper_bound, run_upper_bound: sweep.run_upper_bound, onedrive_parent_id: sweep.onedrive_parent_id, attachment_inventory: Array.isArray(row?.attachment_inventory) ? row.attachment_inventory : [] } };
});

// Purpose: Stamp Immutable Attachment IDs. Keep this deterministic and fail closed.
const parent = $('Shape Immutable Message Inventory').item.json;
return $input.all().map(item => {
    const attachment = item.json || {}, attachmentId = String(attachment.id || '').trim();
    if (!attachmentId) return { json: { message_id: parent.message_id, attachment: null } };
    const identity = parent.message_id + ':' + attachmentId;
    return { json: { message_id: parent.message_id, source_code: parent.source_code, attachment: { id: attachmentId, attachment_identity: identity, name: attachment.name || 'attachment.bin', contentType: attachment.contentType || null, size: attachment.size ?? null, isInline: Boolean(attachment.isInline) } } };
});

// Purpose: Aggregate Immutable Archive Inventory. Keep this deterministic and fail closed.
const sweep = $('Verify Receipt and Return Sweep').first().json, parents = $('Shape Immutable Message Inventory').all().filter(item => !item.json.empty_inventory), rows = $input.all().map(item => item.json), grouped = new Map();
for (const row of rows) {
    const messageId = String(row.message_id || '').trim();
    if (!messageId) continue;
    const bucket = grouped.get(messageId) || [];
    if (row.attachment?.id) bucket.push(row.attachment);
    grouped.set(messageId, bucket);
}
const messages = parents.map(item => {
    const message = item.json, attachments = grouped.get(message.message_id) || [], seen = new Set();
    for (const attachment of attachments) {
        const identity = message.message_id + ':' + attachment.id;
        if (seen.has(identity)) throw new Error('DUPLICATE_MESSAGE_ATTACHMENT_ID');
        seen.add(identity);
    }
    attachments.sort((left, right) => String(left.id).localeCompare(String(right.id)));
    return { message_id: message.message_id, message, attachment_inventory: attachments, attachment_ids: attachments.map(attachment => attachment.id), attachment_identity_keys: attachments.map(attachment => message.message_id + ':' + attachment.id) };
});
return [{ json: { ...sweep, messages, empty_inventory: messages.length === 0, immutable_inventory: true, attachment_ids_verified: true, attachment_identity_keys: messages.flatMap(message => message.attachment_identity_keys) } }];

// Purpose: Verify Attachment Archive Barrier. Keep this deterministic and fail closed.
const result = $json, contract = $('Attach Immutable Inventory to Sweep').first().json;
if (result.attachment_verification_barrier !== 'VERIFIED' || result.attachment_ids_verified !== true || result.email_evidence_receipt_barrier !== 'VERIFIED')
    throw new Error('ATTACHMENT_AND_EMAIL_EVIDENCE_BARRIER_REQUIRED');
const expected = Array.isArray(contract.attachment_identity_keys) ? contract.attachment_identity_keys : [], observed = Array.isArray(result.attachment_identity_keys) ? result.attachment_identity_keys : [];
if (new Set(observed).size !== expected.length || expected.some(identity => !observed.includes(identity)))
    throw new Error('COMPOSITE_ATTACHMENT_IDENTITY_BARRIER_MISMATCH');
if (Number(result.email_evidence_receipts_verified) !== Number(contract.matched_count))
    throw new Error('EMAIL_EVIDENCE_RECEIPT_COUNT_MISMATCH');
return [{ json: { ...contract, ...result, archive_ready: true, cursor_commit_eligible: false } }];

// Purpose: Require Verified Attachment Barrier. Keep this deterministic and fail closed.
const row = $json;
if (row.attachment_verification_barrier !== 'VERIFIED' || row.email_evidence_receipt_barrier !== 'VERIFIED' || row.archive_ready !== true || Number(row.email_evidence_receipts_verified) !== Number(row.matched_count)) throw new Error('DOWNSTREAM_ARCHIVE_AND_EMAIL_BARRIER_MISSING');
return [{ json: row }];

// Purpose: Empty Immutable Archive Inventory. Keep this deterministic and fail closed.
const sweep = $('Verify Receipt and Return Sweep').first().json;
return [{ json: { ...sweep, messages: [], immutable_inventory: true, attachment_ids_verified: true, empty_inventory: true } }];

// Purpose: Attach Immutable Inventory to Sweep. Keep this deterministic and fail closed.
const receipt = $json, inventory = $('Aggregate Immutable Archive Inventory').first().json;
return [{ json: { ...receipt, folder_id: receipt.folder_id, senders: receipt.senders, subjects: receipt.subjects, onedrive_parent_id: receipt.onedrive_parent_id, messages: inventory.messages, immutable_inventory: true, attachment_ids_verified: true, attachment_identity_keys: inventory.attachment_identity_keys || [], empty_inventory: inventory.empty_inventory === true } }];

// Purpose: Return Existing ENUMERATED Receipt. Keep this deterministic and fail closed.
const trusted = $('Freeze Trusted Cursor Window').first().json, receipt = $json;
for (const field of ['run_id','source_code','window_start','run_upper_bound'])
    if (String(receipt[field] ?? '') !== String(trusted[field] ?? '')) throw new Error('ENUMERATED_RECEIPT_READBACK_MISMATCH:' + field);
if (receipt.terminal_state !== 'ENUMERATED' || receipt.pagination_exhausted !== true || receipt.cursor_commit_eligible !== false) throw new Error('ENUMERATED_RECEIPT_REPLAY_NOT_SAFE');
return [{ json: { ...trusted, ...receipt, messages: [], immutable_inventory: true, attachment_ids_verified: true, attachment_identity_keys: [], empty_inventory: true, replay_noop: true, receipt_readback_verified: true, cursor_commit_eligible: false } }];
